/* Regeln – Storm and Root, Kap. 2 „Die erdrückenden Tiefen“, Unter-Gestrüpp-Regeln (Storm and Root S. 52–65) */
window.WS_NACH = window.WS_NACH || {}; WS_NACH.regeln = WS_NACH.regeln || [];
(function(L){ var K = "Die erdrückenden Tiefen";
L.push({id:"sr-unter-gestruepp-regeln", k:K, t:"Unter-Gestrüpp-Regeln", p:52, q:"sr", b:[
 {a:"Die übrigen Seiten dieses Kapitels behandeln Mechaniken rund um Tauchboot-Reisen und die erdrückenden Tiefen und bauen auf den bereits eingeführten erzählerischen Elementen auf. Kurz gesagt umfassen diese Seiten:"},
 {c:"Crezzer-Verderbnis", x:"Eine optionale Regel für die sich verschlimmernden Auswirkungen von Crezzerin bei zunehmender Tiefe."},
 {c:"Feindliche Umgebungen", x:"Konzentriert sich auf die besonderen Bedrohungen, mit denen eine Crew auf Reisen durch die Tiefe meist konfrontiert wird."},
 {c:"Reisen in der Dunkelheit", x:"Mit Ratschlägen zu Bewegung und Kampf in der Tiefe und einer geänderten Wachwurf-Tabelle für Crews, die durch Geflecht, Senke und Tiefe reisen."},
 {c:"Druck", x:"Ein Bündel neuer Regeln und Konventionen, um die Verschlimmerung des körperlichen und seelischen Drucks darzustellen, den Schiffe und Crews beim tieferen Abtauchen erleben. Das umfasst die Druckanzeige (eine besondere Art Leiste, die für die Überwachung der Auswirkungen der Tiefe wichtig ist) und wie die Druckstufe steigt."},
 {c:"Druckfolgen", x:"Eine Reihe von Zufallstabellen, mit denen das Glühwürmchen einer Crew unter Druck seltsame Leiden zufügen kann."},
 {c:"Risse", x:"Eine besondere Art Wendung, die von Natur aus nachteilig ist, aber den Stachel des Drucks vorübergehend nimmt."},
 {h:"Weiterführende Lektüre …"},
 {a:"Neben dem mechanischen Teil dieses Kapitels solltest du dir die Regeln ansehen für:"},
 {c:"Bestimmte Unter-Gestrüpp-Bedrohungen", x:"Sie kommen mit steigendem Druck erst richtig zur Geltung; jede Bedrohung hat ihren eigenen Eintrag im Gefahren-Abschnitt. Schlechte Luft findest du auf S. 139, treibende Sporen auf S. 155, Insekteneinfälle auf S. 152 und wandernde Geister auf S. 169."},
 {c:"Druckhüllen", x:"Gemacht für sicheren Betrieb in der Tiefe; zu finden im Kapitel zur Schiffserstellung auf S. 124."},
 {c:"Luftwäscher", x:"Ein optionales Extra, das das Innere eines Tauchboots sauber und atembar hält; zu finden auf S. 126."}
]});
L.push({id:"sr-crezzer-verderbnis", k:K, t:"Crezzer-Verderbnis", p:53, q:"sr", b:[
 {a:"Optionale Regel. Je tiefer du in die Wildnis abtauchst, desto gefährlicher wird Crezzerin. Zunächst mag das lächerlich scheinen – Crezzerin ist schon auf Gestrüpp-Ebene eine mächtige Bedrohung. Wie könnte es noch schlimmer werden, wenn man tiefer kommt?"},
 {a:"Bei Crezzerin in größerer Tiefe spielen zwei Hauptfaktoren eine Rolle: Allgegenwart und Wirkstärke."},
 {c:"Allgegenwart", x:"Im Gestrüpp kaum ein Problem, droht die schiere Menge an Crezzerin die Unvorbereiteten zu überwältigen, wenn man in die Senke und die Tiefe vordringt. Auf dieser Ebene ist es nicht nur in den Blättern, sondern sickert aus der Rinde, platzt aus Früchten, fließt in Rinnsalen die Stämme hinab oder treibt nebelartig durch die Luft.",
  l:["Erzählerisch verringert das den Anteil sicheren Bodens in extremen Tiefen und macht Reisen außerhalb des Schiffs für jene ohne zusätzlichen Schutz riskanter.","Mechanisch kann es den Abzug auf Aktionen erhöhen, die gemacht werden, um die Tiefen zu durchqueren und dabei eine Verunreinigung zu vermeiden – ein Abzug, der ignoriert werden kann, indem man sich entscheidet, der sengenden Substanz zu trotzen, im Wissen, dass Schaden (oder Schlimmeres) die Folge sein wird."]},
 {c:"Wirkstärke", x:"Es gibt nicht nur mehr von der gefährlichsten Substanz der Wildsee unterhalb des Geflechts, auch die Konzentration steigt im Gleichschritt. Starkes Crezzerin wirkt schneller auf Körper und Geist, verursacht mehr Schmerz und, vielleicht am wichtigsten, überwältigt die herkömmlichen Methoden, einen Wildsegler zu schützen.",
  l:["Erzählerisch sind die Auswirkungen von Crezzerin auf Crew und Gefahren ausgeprägter – mehr Schmerz, mehr Mutation und ungewöhnlichere geistige Wirkungen.","Mechanisch bedeutet das, dass in der Senke und der Tiefe alle Charaktere ihre Resistenz gegen Crezzerin um eine Stufe senken. Ein Charakter, der normalerweise immun gegen Crezzerin ist, wäre resistent, ein normalerweise resistenter Charakter hätte keine Resistenz dagegen, und ein Charakter ohne jede angeborene Resistenz erhielte eine Schwäche."]},
 {h:"Umgebungs-Crezzerin"},
 {a:"Mögliche Ursachen: Alles Natürliche in der Tiefe hat ein gewisses Maß Crezzerin in sich und wird so zu einer ständigen, wachsenden Gefahr. Bestien, Pflanzen, Nebel, Wasser … Manchmal sogar die Luft selbst.\nMögliche Auswirkungen (Schiff): Werte, Räume, Schiffskomponenten … Bei den Crezzer-Verunreinigungsgraden in der Senke und darunter ist das Schiff selbst in Gefahr der Mutation (ganz zu schweigen von Säure- und Giftschaden in massivem Ausmaß). Das kann eine Leiste in Gang setzen, die auf einen schweren Defekt des Schiffs hinzählt, oder fast sofortige Wirkung haben.\nMögliche Auswirkungen (Crew): Crezzer-Verunreinigung, oft als langsamer Vorgang betrachtet, ist in der Tiefe grauenhaft beschleunigt. Das zeigt sich meist in Verletzungen, Mutationen, die Gestalt oder Denken eines Einzelnen verändern, und massivem Gift- oder Säureschaden in Form von verbrennenden statt markierenden Leisten. Bereiche mit dichtem Crezzerin verursachen zudem wahrscheinlich Morast durch Halluzinationen und eigentlich unmögliche körperliche Veränderungen.\nWenn du Crezzerin als Umgebungsgefahr einsetzen willst, beachte folgende Richtlinien …\nRelevante Werte: Sägen schneiden durch crezzerreiches Laub, was die unmittelbare Gefahr erhöht, das Schiff aber vielleicht an einen sichereren Ort bringt. Dichtung und Panzerung schützen eine Crew, solange sie in ihrem Schiff ist, können dabei aber aus ihrer üblichen Form verdreht werden."},
 {bsp:"Crezzer-Verderbnis im Spiel", z:[
  ["Glühwürmchen","In der Stille nach diesem fernen Brüllen merkt ihr etwas, das ihr vorher nicht wahrnehmen konntet. Inge, dein Gehör ist das beste von allen, glaube ich?"],
  ["Inge","Ja, das haben wir, denke ich, geklärt. Höre ich es zuerst, oder bin ich die Einzige, die hört, was auch immer das ist?"],
  ["Glühwürmchen","Alle hören es, aber du kannst die Quelle bestimmen: ein leises Zischen, wie Fett, das in einer heißen Pfanne rollt."],
  ["Laura","Das klingt nicht nach etwas, das wir hören wollen. Inge?"],
  ["Inge","Ja, definitiv nicht. Woher kommt es?"],
  ["Glühwürmchen","Vom Rumpf."],
  ["Inge","Definitiv, definitiv nicht! Ich packe Kyllian und renne zur Kabinenseite und öffne eines der Bullaugen, um besser zu sehen. Was passiert da draußen?"],
  ["Glühwürmchen","Nun, du hast die richtige Person mitgenommen! Kyllian, du hast mehr Erfahrung mit Crezzerin als jeder andere in der Crew, und was du da draußen siehst, ist definitiv ein Crezzer-Effekt – die hölzernen Teile des Rumpfs werfen sich leicht auf und schwärzen sich langsam."],
  ["Kyllian","Aber das Rumpfholz ist doch behandelt, oder? Versiegelt?"],
  ["Glühwürmchen","Gegen normales Crezzerin, ja. Aber hier unten ist die Wirkstärke stark gestiegen. Je länger ihr bleibt und je tiefer ihr geht, desto schlimmer wird es. Ich lege eine Leiste an …"]]}
]});
L.push({id:"sr-feindliche-umgebungen", k:K, t:"Feindliche Umgebungen", p:54, q:"sr", b:[
 {a:"Durch das Geflecht und darunter zu reisen ist von Natur aus gefährlicher, als über die rauschenden Wellenkämme zu gleiten (was an sich schon ziemlich gefährlich ist). Selbst mit den besten Vorbereitungen ist es für ein Tauchboot fast unmöglich, sich vor jeder möglichen Umgebungsgefahr zu schützen, der es in der Tiefe begegnen könnte, und da sind die Geschöpfe, die dort ihr Zuhause haben, noch gar nicht eingerechnet.\nObwohl Werften und Reparaturbuchten einfallsreich darin sind, das Beste aus dem verfügbaren Bergegut herauszuholen, sind die meisten Schiffe im Wesentlichen noch immer eine Masse aus Gebrauchtteilen und Wipfel-Kuriositäten. Diese zusammengeflickte Bauweise funktioniert auf Blätterdach-Ebene bestens, lässt aber viel zu wünschen übrig, wenn die Äste sich schließen und die Luft dick wird – das Abtauchen unter das Gestrüpp bringt eine ganze Reihe von Problemen und Zumutungen mit sich, mit denen das durchschnittliche Schiff vielleicht nicht fertigwird.\nDiese Seite behandelt diese Probleme mit einer Reihe erzählerischer und mechanischer Effekte, die an die vier verbreitetsten Umgebungsgefahren des Unter-Gestrüpps geknüpft sind: schlechte Luft, treibende Sporen, Insekteneinfälle und wandernde Geister. Mit all dem hatten Wildsegler auf irgendeine Weise an der Oberfläche zu tun, doch diese Bedrohungen werden durch Druck, Isolation und die einzigartigen Ökosysteme der Tiefe vergrößert."},
 {c:"Schlechte Luft", x:"Wildsee-Schiffe sind für vieles bekannt, aber hochwertige Handwerksarbeit zählt selten dazu. Der Gedanke, dass das Innere eines Schiffs „luftdicht“ sei, ist angesichts der Materialien, mit denen Ingenieure arbeiten müssen, und der ständigen baulichen Belastung und des Durchrüttelns bei der Reise durch eine Welt aus Blatt und Ast lachhaft.",
  l:["Relevante Werte: Dichtung, um das Innere eines Schiffs zu schützen; Sägen, wenn ein Schiff einen Antrieb hat, der die Luft um sich bewegen könnte.","Mögliche Quellen: Aufsteigende Hitze, überwältigende Feuchtigkeit, Leviathan-Atem oder -Moschus, Gase aus Unter-Traufe-Schloten oder räuberischen Pflanzen, der Gestank des Lagers einer Kreatur.","Mögliche Auswirkungen (Schiff): Ätzende Nebel könnten Panzerung oder Dichtung zersetzen. Hitze (oder, seltener, Kälte) könnte manche Bisse und Motoren weniger wirksam machen und so die Tempo- oder Sägen-Werte eines Schiffs beeinträchtigen.","Mögliche Auswirkungen (Crew): Abzug auf Aktionen durch Sauerstoffmangel oder das Würgen durch Übelkeit. Verringerte Wucht auf Aktionen, um durch Hitzeflimmern oder tränende Augen zu sehen. Schaden an Eigenschaften durch eingeatmete Gifte oder an Ausrüstung durch ätzende Stoffe. Verletzungen in Form von Krankheiten, die sich festsetzen oder verschlimmern."]},
 {c:"Treibende Sporen", x:"Ohne Wind, der sie verteilt, werden Sporenwolken in der Tiefe immer dichter, bis ein Wurzelbeben oder ein vorbeiziehender Leviathan sie aufwirbelt, Oberflächen überzieht und poröse Materialien mit schnell wachsenden Pilzen besät (oder weit unangenehmere Wirkungen heraufbeschwört).",
  l:["Relevante Werte: Dichtung, um Sporen draußen zu halten, wo sie hingehören; Panzerung, um Sporen etwas zu geben, worauf sie sich setzen können, das weder die Crew noch die „zarteren“ Teile eines Schiffs sind.","Mögliche Quellen: Pilz-Leviathane, zerstörte Mykosanktorien, Sporenschlote, die in unregelmäßigen Abständen Schwaden ausstoßen, lebende Sporenwolken (die ein Schiff ähnlich jagen wie ein lebender Sturm), verrottete oder beschädigte Eisenwurzel-Bäume, verwesende Kadaver, das Haskavo-Netzwerk.","Mögliche Auswirkungen (Schiff): Sporen, die Motor oder Biss verstopfen, könnten Vorwärtspreschen unmöglich machen, das Tempo verringern oder die Fähigkeit eines Schiffs beeinträchtigen, den Neigungs-Wert zu nutzen. Wachsender Pilz kann mit der Zeit Panzerung und Dichtung zerfressen.","Mögliche Auswirkungen (Crew): Aufgaben, um Pilzinfektionen von Ausrüstung, Eigenschaften oder Gefährten zu entfernen. Husten und Keuchen, wenn die Luft sich füllt, oder Verlust von Sicht oder Gehör durch die Wolken. Morast durch Halluzinationen."]},
 {c:"Insekteneinfälle", x:"Von Leben, Licht und Lärm angelockt, sind Schwärme in der Dunkelheit unten eine krabbelnde, stechende, huschende Gefahr, die fast unmöglich fernzuhalten ist, sobald sie deine Witterung aufgenommen haben. Dazu kommt die Möglichkeit sich entwickelnder Schwarmintelligenzen und Pseudotzeli-Gefahren, die sich mit taktischer Präzision bewegen können … Abtauchende Wildsegler tun gut daran, ihre Umgebung jederzeit im Auge zu behalten.",
  l:["Relevante Werte: Dichtung, um zu verhindern, dass ein Schwarm Zugang erhält; Neigung oder Tempo, um eine heranrückende Masse abzuschütteln und ihr davonzufahren; Tarnung, um zu versuchen, keine Aufmerksamkeit zu erregen.","Mögliche Quellen: Aufgestörte Nester, Insektenwanderungen, jagende Schwarmintelligenzen, Kadaverfeste.","Mögliche Auswirkungen (Schiff): Insektenschwärme können ernste bauliche Schäden an einem Schiff verursachen, indem sie Motoren verkleben, und Ressourcen und Fracht zerstören (oder davontragen). Abzug auf Sägen und Tempo bei der Fahrt durch einen Schwarm ist üblich.","Mögliche Auswirkungen (Crew): Schaden und Krankheiten durch Bisse und Stiche, Morast durch die Bedeckung mit krabbelnden Gestalten, Abzug beim Durchqueren von insektenverstopften Bereichen."]},
 {c:"Wandernde Geister", x:"Je näher man der Traufe kommt, desto stärker wird die spirituelle Präsenz der Wildnis. Sie kann sich in Visionen zeigen, in Spukerscheinungen, sogar in treibenden Gespenstern, denen eine Art dunkelgebundene Körperlichkeit verliehen wurde.",
  l:["Relevante Werte: Tempo, um einer treibenden Seele zu entkommen; Tarnung, um einen Graveling-Hain nicht aufzuschrecken.","Mögliche Ursachen: Nähe zur Unter-Traufe, verlorene Segler, an der Wirklichkeit klammernde Bestienseelen, Wracks.","Mögliche Auswirkungen (Schiff): Geister beeinflussen ein Schiff selten und konzentrieren sich lieber auf die Crew darin, doch manche könnten sich an Motoren zu schaffen machen oder bestimmte Räume heimsuchen.","Mögliche Auswirkungen (Crew): In Bereichen hoher spiritueller Aktivität sind gestörter Schlaf und prophetische Träume üblich, was Ruhe fast unmöglich macht und von langfristigen Aufgaben ablenkt, in Form von Abzug oder zusätzlichen Kästchen auf Leisten. Rachsüchtigere Geister könnten einen Einzelnen verfolgen und Schaden oder Morast zufügen."]}
]});
L.push({id:"sr-feindliche-umgebungen-nutzen", k:K, t:"Feindliche Umgebungen nutzen", p:55, q:"sr", b:[
 {a:"Auch wenn all diese Umgebungsbedrohungen als eigene Gefahr oder Begegnung eingesetzt werden können, funktionieren sie oft am besten als Kulisse für ein anderes Ereignis. Ein Rudel Nadelwölfe zu bekämpfen mag für erfahrenere Wildsegler zum Alltag gehören, doch dies in einer Wolke ablenkender Geister zu tun, die die Wahrnehmung der Crew verzerren, bringt wahrscheinlich eine Prise Unerwartetes ins Geschehen.\nUnten findest du eine kurze Übersicht, wie verschiedene Szenentypen davon betroffen sein könnten, dass die Crew oder ihr Tauchboot sich durch eine feindliche Umgebung bewegt, die von einer dieser Bedrohungen beherrscht wird."},
 {c:"Szenen", x:"Szenen der Erkundung und Verständigung könnten wegen der umgebenden Umgebungsgefahren einen strengen Zeitleisten-Zähler erhalten, wobei NSC nicht reden wollen, bis die Bedrohungen vorüber sind. Kampfszenen werden weit gefährlicher oder komplexer, wenn die Crew ihre Aufmerksamkeit zwischen zwei unabhängig agierenden Bedrohungen aufteilen muss."},
 {c:"Montagen", x:"Montage-Aktionen, die an Orten ohne Resistenz oder Immunität gegen diese feindlichen Kräfte ausgeführt werden, könnten Würfe erfordern, wo sonst keine nötig wären, oder verringerte Wucht haben, wenn die Bedrohung die gewählte Aufgabe eines Wildseglers stört. Aufgaben an Deck eines Schiffs ohne eingerastete Druckhülle sind meist am stärksten betroffen."},
 {c:"Reisen", x:"Alle Umgebungsgefahren, die links erwähnt wurden, können den Fortschritt eines Schiffs verlangsamen, doch viele können auch die Navigation durcheinanderbringen. Crews könnten sich vom Kurs abgebracht oder in der Dunkelheit völlig verirrt finden. Auf der nächsten Seite findest du einige zusätzliche Regeln für Reisen durch die Senke und die Tiefe."}
]});
L.push({id:"sr-reisen-dunkelheit", k:K, t:"Reisen in der Dunkelheit", p:56, q:"sr", b:[
 {erz:"Oben war die Unter-Gestrüpp-Plattform etwas Neuartiges gewesen, eine Kuriosität – ein Blick hinab unter das Schiff, an den Blättern der Wipfel vorbei. Er hatte dort gesessen und darüber nachgedacht, was Meilen unter ihnen liegen mochte, welche Stücke Geschichte sie überfuhren, ohne es je zu wissen. Welche Geheimnisse die Wellen nie verraten würden.\nAber hier unten, in der Senke, fühlte sich die Plattform anders an.\nDie Druckhülle reichte zurück, um sie zu bedecken, sie war also nicht weniger geschützt als der Rest des Schiffs. Sie war aus massivem Eisen und netzverstärktem Bernstein, und auch wenn gelegentlich eine Klaue oder eine Dornenranke über die breiten Fenster kratzte, waren es nicht diese Störungen, die ihn nervös machten.\nEs waren die Geheimnisse, an die er gedacht hatte. Die Ruinen, der Verlust. Von der Oberfläche aus hatte das alles so aufregend gewirkt.\nAber hier unten wirkten sie nur noch wie ein Versprechen."},
 {a:"Auch wenn die eigentliche Mechanik des Reisens unter den Wellen dieselbe ist, ist die Erfahrung eine sehr andere – besonders, wenn man auf Wache geht. Sofern das Gebiet, in dem du bist, keine ordentliche Lichtquelle hat (das können leuchtende Pilze, glimmende Nebel, tanzende Leuchtkäfer oder die Lichter des Schiffs sein, auf dem du fährst), spähst du in ein verschattetes Durcheinander aus Ästen und beobachtest wahrscheinlich Bewegung inmitten eines Meeres aus Bewegung. Das ist selbst für erfahrene Taucher eine nervenaufreibende Tätigkeit, und du markierst vielleicht öfter Morast, wenn du deine Zeit damit verbringst, in die Tiefen zu starren."},
 {h:"Wachwürfe & Bedrohung im Tauchboot"},
 {a:"Der einzige mechanische Unterschied bei Wachwürfen liegt im Bedrohungswurf des Glühwürmchens, dem Wurf, der die mögliche Gefahr dessen bestimmt, was der Wachwurf enthüllt. Sofern die Crew nicht durch eine von Tiefhafen-Verteidigungen patrouillierte Region fährt oder unter dem Schutz einer bestimmten freundlichen Instanz steht (in diesem Fall würfelt das Glühwürmchen wie gewohnt einen einzelnen W6), liegt der grundlegende Bedrohungswurf für Tauchboote bei 2W6, wobei das Glühwürmchen das höchste Ergebnis abzieht.\nEine passende Seekarte zu besitzen hilft auch beim Reisen in der Tiefe – in diesen Fällen würfelt das Glühwürmchen vor dem Abzug einen zusätzlichen W6 und nimmt dann das höchste verbleibende Ergebnis."},
 {h:"Wachwurf-Ergebnisse für die Tiefen"},
 {c:"Spannung (6)", x:"Unter Druck gibt es keinen Frieden, aber es gibt ruhigere Momente. Du erlebst vielleicht …",
  l:["Ein Bruchstück von etwas, das der Sicherheit nahekommt, genug für eine Montage. Nützlich zum Heilen und Reparieren.","Eine Zusammenkunft unter der Druckhülle, abgeschirmt von der Wildnis, die sich um das Schiff drängt.","Eine Gelegenheit, ein Flüstern in der Dunkelheit zu gewinnen, indem man eine leise Geschichte erzählt, von Vorsicht, Sicherheit oder Stille.","Die Unterbesatzung stimmt einen Chor an, ein Baumlied, das Sorgen fernhalten soll.","Ein Problem mit der Unterbesatzung, das die Crew zum Eingreifen und Schlichten zwingen könnte.","Manchmal ist es am besten, sich in die Kajüte zurückzuziehen und einen Moment zur Ruhe zu kommen. Heilt meist Morast."]},
 {c:"Ordnung (4–5)", x:"Die Tiefen mögen feindlich sein, doch sie sind kaum frei von Zivilisation. Du erlebst vielleicht …",
  l:["Ein Tauchboot, das nahe genug durch das Laub bricht, dass ihr es anrufen könnt.","Die Sichtung eines Tiefhafens, von einer kleinen umschlossenen Siedlung bis zu einer Unter-Gestrüpp-Stadt.","Einen Überlebenden, einen von seinem Schiff getrennten Taucher oder einen glücklosen Wildsegler, der nach einem Sturz im Geäst hängt.","Ein Wrack oder eine Ruine, entweder eines anderen Tiefsee-Schiffs oder von etwas, das von der Oberfläche versunken ist.","Ein Lager oder eine Rettungsboje, eine kleine Oase möglichen Komforts und möglicher Ressourcen inmitten des Drucks.","Ein Hauch von Verschwörung, einer Wahrheit, die Blätterdach-Bewohnern verborgen, in der Dunkelheit aber enthüllt ist."]},
 {c:"Natur (1–3)", x:"Dort unten ist alles Natur, aber manches verlangt mehr Aufmerksamkeit als der Rest. Du erlebst vielleicht …",
  l:["Eine unerwartete Druckänderung, die die Stimmung heben oder grausam zerschmettern könnte.","Ein bemerkenswertes Wahrzeichen, ein Merkmal der erdrückenden Tiefen, das bei der Wegfindung und Kartenerstellung hilft.","Ein Wunder der Tiefe oder ein freundliches Licht in der Dunkelheit. Heilt Morast.","Einen Schrecken, der sich im Geist einnistet, oder ein Wrack oder eine Ruine, die völlig überrannt wurde. Markiert Morast.","Ein Stück festen Grunds, von der Oberfläche versunken oder von unten emporgehoben – Landfall. Gut für Ressourcen.","Die wahre Wildnis der Tiefe nimmt der Oberfläche den Eindringling übel – eine Pflanze, Kreatur oder Naturgewalt."]}
]});
L.push({id:"sr-bewegen-kaempfen-tiefe", k:K, t:"Bewegen & Kämpfen in der Tiefe", p:57, q:"sr", b:[
 {h:"Sich in der Tiefe bewegen"},
 {a:"Sich im Schiff umherzubewegen ist unter Wasser nicht schwieriger als an der Oberfläche, solange man eine funktionierende Druckhülle hat. Doch sobald diese Hülle bricht, birgt selbst das Überqueren des Decks ein Gefühl der Gefahr für jedes Crewmitglied, das nicht vollständig mit einer Art Druckanzug ausgerüstet ist – die Schwärme, die Dunkelheit, das Gefühl, klein und beutehaft in einer Welt größerer Raubtiere zu sein … Es setzt einem nach einer Weile zu, und diese Weile ist ziemlich kurz.\nSich um das Äußere eines Schiffs zu bewegen, das im Geflecht oder darunter ist, etwa um Reparaturen durchzuführen oder einen Schlot zu entstopfen, ist ein zweischneidiges Schwert. Solange du genug Resistenz gegen Crezzerin hast, bieten die zahlreichen nahen Äste zusätzliche Gelegenheiten, von Ort zu Ort zu klettern und zu krabbeln. Aber die meisten Reparaturen brauchen Licht, und Licht zieht in einer meist lichtlosen Welt Aufmerksamkeit an."},
 {h:"In der Tiefe kämpfen"},
 {a:"Mit genug Übung kann die Umgebung unter den Wellen für einen Wildsegler als Kampfarena ebenso vorteilhaft sein wie für die Geschöpfe, die dort natürlich leben (größtenteils jedenfalls). Besonders für Kämpfer, die auf Bewegung und Heimlichkeit setzen, kann die Kombination aus Dunkelheit, zahlreichen Trittmöglichkeiten und mehreren Orten zum Verstecken oder Zurückziehen bei einer Konfrontation ein Segen sein. Guerilla-Taktiken und Zuschlagen-und-Rückzug-Angriffe sind am wirksamsten, doch Segler sollten bedenken, dass es manchmal am besten ist, empfindungsfähigen Gefahren unter den Wellen zu begegnen, indem man sich unter Deck zurückzieht, die Türen verriegelt und wartet, bis sie vorüberziehen."}
]});
L.push({id:"sr-druck", k:K, t:"Druck", p:58, q:"sr", b:[
 {erz:"Sie hatte die Wendung schon gehört. „Ein Spinnennetz aus Rissen“. Sie hatte immer so schön geklungen, in den wenigen Malen, in denen es ihr durch den Kopf gegangen war – die Vorstellung, dass Bernstein in einem Sekundenbruchteil, einem zu kleinen Zeitabschnitt, um ihn zu zählen, von einem Zustand in einen anderen übergeht. Etwas Glattes und Klares und Schönes, das zu einer zerklüfteten, zerbrochenen Wolke der Vergangenheit wird. Schön.\nIn der Theorie.\nAber als die Nostromika sich durch die letzten Verwicklungen des Geflechts und in die völlige, dornengestrüppverstopfte Dunkelheit der Senke gerissen hatte, wirkten diese Gedanken wie ein grausamer Scherz. Das Knarren der Schiffsstruktur um sie her war ein weit gegenwärtigerer, weit drängenderer Gedanke. Das erstickte Husten des Motors, das Mahlen der Sägen … Und das Bullauge neben ihr, das sich im kleinsten Augenblick in ein Spinnennetz aus Rissen über einem vergessenen Sonnenuntergang verwandelte.\nUnd doch tauchten sie weiter ab."},
 {a:"Als natürliches Nebenprodukt des Erkundens dort unten, wo die Äste die Sonne versperren, ist Druck für Wildsegler (und ihre Schiffe) beim Erkunden der unteren Schichten der Welt sowohl ein körperliches als auch ein seelisches Problem.\nDie Wirkungen von Druck unterscheiden sich von Crew zu Crew, von Abtauchen zu Abtauchen, manchmal sogar von Segler zu Segler. Druck kann sich zeigen als:"},
 {l:["Das Gefühl, dass etwas zutiefst falsch ist, die Unfähigkeit, das scharfe Bewusstsein für die Tiefe und die Gefahr abzuschütteln, die ein Schiff von allen Seiten bedrängen.","Das Knarren und Ächzen der Schiffsbalken, wenn Dichtungen aufspringen und Bullaugen reißen.","Eine Veränderung in der Wildnis, wenn Sporen die Luft trüben und Äste sich unnatürlich zu verdrehen beginnen.","Die Aufmerksamkeit von Bewohnern, die man besser in Ruhe ließe, wenn sie die Witterung eines Schiffs aufnehmen, das in ihr Revier fährt."]},
 {a:"Der Druck, unter dem ein Schiff und seine Crew stehen, wird vom Glühwürmchen verfolgt, wobei die Einzelheiten zu Leistenlänge und Zahl markierter Kästchen den anderen Spielern unbekannt sind."},
 {h:"Die Druckanzeige"},
 {a:"Die Druckanzeige ist ein leistenbasiertes System zur Messung des Druckanstiegs, dem ein Schiff und seine Crew in der Tiefe ausgesetzt sind. Sie besteht aus einer Druckstufe (dargestellt durch einen größeren Kreis mit einer Zahl darin) links und einer Druck-Leiste (dargestellt durch eine Kette verbundener Kreise) rechts."},
 {h:"Druckstufe"},
 {a:"Die Druckstufe beginnt bei null und kann bis auf drei steigen. Je höher die Druckstufe, desto spürbarer werden die Auswirkungen des Reisens in der Tiefe – vielleicht auf das Schiff, vielleicht auf die Crew, vielleicht auf beides zugleich. Hier ein Beispiel …"},
 {a:"Die Crew der Jailbird taucht tiefer in das Unterblätterdach ab, auf der Spur eines seltenen Krauts, das nur in stockfinsterer Dunkelheit wächst. Der Druck, unter dem sie stehen, nimmt auf der Reise zu – er beginnt bei Stufe null, während die Crew sich so gut sie kann an das Gefühl des tieferen Abtauchens gewöhnt. Bei Stufe eins bemerken sie, dass etwas von draußen den Weg in ihr Schiff gefunden hat, aber sie können es nicht aufspüren. Bei Druckstufe zwei beginnt der Geist ihrer Slingerin sich aufzulösen, und sie müssen anhalten, um sie zu beruhigen und im Zaum zu halten, während sie versucht, aus dem „verseuchten“ Schiff zu entkommen. Bei Druckstufe drei erkennen sie ihre Torheit – Mitglieder ihrer Unterbesatzung verschwinden, Schiffssysteme fallen aus, und das Unwohlsein der Slingerin breitet sich wie ein Lauffeuer durch den Rest der Crew aus."},
 {tab:{k:["Druckstufe","Beispiel: Die Jailbird"],z:[
  ["0","Die Crew passt sich so gut sie kann an das Gefühl des tieferen Abtauchens an."],
  ["1","Etwas von draußen hat den Weg ins Schiff gefunden, aber sie können es nicht aufspüren."],
  ["2","Der Geist ihrer Slingerin beginnt sich aufzulösen; sie müssen anhalten, um sie zu beruhigen und im Zaum zu halten."],
  ["3","Unterbesatzungs-Mitglieder verschwinden, Schiffssysteme fallen aus, das Unwohlsein der Slingerin breitet sich durch die Crew aus."]]}},
 {h:"Druck-Leiste"},
 {a:"Die Länge einer Druck-Leiste wird teils von der Situation bestimmt, teils vom Glühwürmchen, vor allem aber von der Bauweise des Schiffs. Die Kästchen der Leiste können durch eine Vielzahl von Aktionen markiert (oder geleert) werden (auf der nächsten Seite mehr dazu, wie man Leisten festlegt und füllt). Wenn eine Leiste sich füllt, steigt die Druckstufe. Hier ein weiteres Beispiel …"},
 {a:"Die Crew der Jailbird ist bei Druckstufe eins und sucht nach dem unbekannten Eindringling auf ihrem Schiff. Ihr Rattlehand beschließt, auf den Rumpf hinauszugehen, um herauszufinden, wie er hineingelangt ist, und sein Verlassen des Schiffs markiert ein Kästchen auf der Leiste. Ein weiteres Kästchen wird markiert, als ihre Slingerin ein Mitglied der Unterbesatzung findet, das sich in einer Ecke duckt und von einer geschmeidigen Gestalt faselt, die im Gang an ihm vorbeigestreift sei. Ihr Scheitern, die Kreatur aufzuspüren, und die Verzögerung ihrer Reise dadurch markieren ein weiteres Kästchen … Und sie müssen noch immer tiefer."}
]});
L.push({id:"sr-druck-aufbauen", k:K, t:"Druck aufbauen & senken", p:59, q:"sr", b:[
 {h:"Druck aufbauen"},
 {a:"Druck beginnt zuzunehmen, sobald eine Crew unter die Umarmung des Geflechts taucht, eine heimtückische Gefahr, die die Bedrohung durch Schaden, Morast und unerwartete Dunkelheit mit sich bringt. Wenn die Druckstufe steigt, weil eine Druck-Leiste vollständig markiert wird, leere die gesamte Leiste. Wenn die Druckstufe aus einem anderen Grund steigt, bleiben die Markierungen auf der Leiste, wie sie sind."},
 {tab:{k:["Wirkung","Auslöser"],z:[
  ["Druck-Leiste: Kästchen markieren","das Schiff (oder die Crew) sich mit einem Tiefen-Leviathan einlässt oder auf einen Schrecken der tieferen Wellen stößt"],
  ["Druck-Leiste: Kästchen markieren","die Crew den Anker wirft oder über Nacht rastet"],
  ["Druck-Leiste: Kästchen markieren","die Crew ihr Schiff verlässt (auch freiwillig)"],
  ["Druck-Leiste: Kästchen markieren","die Dichtungs- oder Panzerungs-Werte des Schiffs Schaden nehmen"],
  ["Druckstufe steigt","das Schiff (oder die Crew) in eine tiefere Schicht der Wildnis wechselt (vom Gestrüpp ins Geflecht, vom Geflecht in die Senke, von der Senke in die Tiefe oder von der Tiefe ins Dunkel-unter-der-Traufe)"],
  ["Druckstufe steigt","die Kästchen der Druck-Leiste vollständig markiert sind"]]}},
 {h:"Druck senken"},
 {a:"Die Druck-Leiste zu markieren ist ein natürlicher Teil der Erkundung des Unterblätterdachs, doch Wildsegler sollten vorsichtig sein, wenn die Druckstufe zu steigen beginnt. Die Folgen können schwer zu bewältigen sein, und während Markierungen gelöscht werden können, ist es weit schwerer, die Druckstufe zu senken, ohne zur Oberfläche zurückzukehren."},
 {tab:{k:["Wirkung","Auslöser"],z:[
  ["Druck-Leiste: Markierung leeren","das Schiff (oder die Crew) auf ein Wunder der tieferen Wellen stößt oder eine direkte Leviathan-Begegnung mit seinem Schiff unversehrt überlebt"],
  ["Druck-Leiste: Markierung leeren","ein Spieler beschließt, eine Wendung durch einen Riss zu ersetzen (einmal pro Szene); die Riss-Regeln stehen auf S. 64"],
  ["Druck-Leiste: Markierung leeren","die Crew einen sicheren Hafen unter den Wellen findet"],
  ["Druck-Leiste: Markierung leeren","ein beschädigter Dichtungs- oder Panzerungs-Wert repariert wird"],
  ["Druckstufe sinkt","das Schiff in einem Tiefhafen anlegt (einmal pro Reise); das Anlegen in einem nautilisierten Tiefhafen senkt die Druckstufe und leert alle Markierungen der Druck-Leiste"],
  ["Druckstufe sinkt","das Schiff (oder die Crew) in eine höhere Schicht der Wildnis wechselt"]]}},
 {h:"Druck-Leisten festlegen"},
 {a:"Die Leiste für die Druckanzeige eines Schiffs festzulegen ist Aufgabe des Glühwürmchens und teils Kunst, teils Wissenschaft (wie so vieles in der Wildsee)."},
 {h:"Die Wissenschaft"},
 {a:"Bestimmte Schiffs-Aufrüstungen (meist die Druckhülle und der Luftwäscher) fügen der Druck-Leiste eine Anzahl Kästchen hinzu – je besser dein Schiff vor den Verheerungen der Tiefe geschützt ist, desto mehr Markierungen kannst du machen, bevor die Stufe steigt und die Crew die negativen Auswirkungen ihrer Erkundung zu spüren beginnt."},
 {h:"Die Kunst"},
 {a:"Die Kunst liegt in der Hand des Glühwürmchens, die Entscheidung, mit wie vielen Kästchen die Druck-Leiste beginnen soll, bevor sie durch das Schiff verändert wird. Das hängt davon ab, in welcher Region der See die Crew ist, wie geistig vorbereitet sie ist, tief unter die Wipfel abzutauchen (da Druck sowohl ein körperliches als auch ein seelisches Phänomen ist), und ob das Glühwürmchen denkt, dass die Crew eine leichte oder eine schwere Fahrt erleben sollte.\nHier ein grober Leitfaden für die künstlerischere Seite des Festlegens von Druck-Leisten:"},
 {l:["Beginne standardmäßig mit einem Kästchen.","Wenn die Crew gut vorbereitet ist, füge ein oder zwei Kästchen hinzu.","Wenn du ihnen Zeit zum Erkunden dort unten geben willst, gib ein weiteres Kästchen oder zwei (das ist besonders angebracht für den ersten Abstecher einer Crew in die Tiefe, wenn du einen „sanfteren“ Einstieg in die Abtauch-Mechanik willst)."]},
 {a:"Es gibt auch die Möglichkeit, die Anzahl der Kästchen auf der Druck-Leiste während eines Abtauchens in die Tiefe zu erhöhen oder zu verringern. Obwohl die Leiste verborgen ist, kann es den Ernst der erdrückenden Tiefe richtig verdeutlichen, wenn man die Spieler informiert, dass sie nicht nur markiert wird, sondern beim Abstieg auch kürzer wird.\nAnders als Aspekt-Leisten können Druck-Leisten leicht über acht Kästchen hinausgehen."},
 {tab:{k:["Druck-Leiste festlegen","Kästchen"],z:[
  ["Standard","1"],
  ["Crew gut vorbereitet","+1 oder +2"],
  ["Zeit zum Erkunden gewähren (besonders beim ersten Abtauchen)","+1 oder +2"],
  ["Ausrüstung des Schiffs (meist Druckhülle und Luftwäscher)","+ Kästchen laut Ausstattung"]]}},
 {bsp:"Druck im Spiel", z:[
  ["Glühwürmchen","Das Bernsteinglas des Tiefhafens ist rasch von Blättern verdeckt, als ihr ablegt, das Zischen der Druckdichtungen, die sich wieder an ihren Platz schieben, das letzte Geräusch, das ihr aus dem Inneren hört."],
  ["Todd","Mach’s gut, Redcliff. Du warst ein gemeiner kleiner Hafen, aber du warst gut zu uns."],
  ["Laura","… Waren sie definitiv nicht, weißt du."],
  ["Todd","Na gut, es war ein Höllenloch. Ich wollte nur positiv bleiben!"],
  ["Glühwürmchen","Und das ist nicht die schlechteste Einstellung, denn was auch immer ihr dort drin durchgemacht habt, ist nichts gegen das, was hier draußen auf euch wartet. Ich lege die Druckanzeige an, mit der Stufe bei null beginnend. Wie lang wird diese Leiste – was gibt euch das Schiff?"],
  ["Kyllian","Plus eins von der Daumenwachs-Beschichtung und plus vier vom Oberkiefer, den wir als Druckhülle haben."],
  ["Glühwürmchen","Und ihr bekommt standardmäßig noch ein einzelnes Kästchen, also habt ihr mindestens sechs Kästchen pro Stufe der Druck-Leiste … Vorerst. Sie könnte kürzer werden, denkt dran, wenn ihr in feindlichere Gebiete vordringt."],
  ["Inge","Was wir, mit Todd am Steuer, ganz bestimmt tun werden."],
  ["Todd","Und damit ist es Zeit, tiefer zu gehen! Das markiert sie nicht, oder?"],
  ["Glühwürmchen","Im Moment nicht, nein. Vorerst könnt ihr das wie eine gewöhnliche Reise behandeln. Na ja, fast – ich beginne mit dem Markieren, wenn eure defensiveren Werte beschädigt werden oder ihr in Schwierigkeiten geratet. Oder auf Schrecken stoßt. Oder …"],
  ["Laura","Ich glaube, wir haben das Bild."],
  ["Todd","Und es wird uns nicht aufhalten! Tauchen wir ab!"]]}
]});
L.push({id:"sr-druckfolgen", k:K, t:"Druckfolgen", p:60, q:"sr", b:[
 {a:"Wenn der Druck steigt, wird es schlimmer. Dramatisch.\nDie Tiefen sind aus gutem Grund für die meisten vernünftigen Wildsegler tabu. Wachsender Druck bringt eine Vielzahl negativer Auswirkungen mit sich, einige auf den Geist, einige auf den Körper, einige auf das Schiff, das dich dort hinunterträgt.\nWenn die Druckstufe einer Crew steigt, muss das Glühwürmchen eine Wahl treffen. Es kann entweder …"},
 {l:["einen andauernden Effekt, mechanisch oder erzählerisch, für die Crew schaffen, den sie erleiden muss.","auf den Tabellen rechts würfeln, um zu sehen, welche Druckfolge die Crew bewältigen muss.","die Wirkung einer bestehenden andauernden Druckfolge steigern.","zwei oder mehr der obigen Optionen zu einem einzelnen Ereignis kombinieren (besonders nützlich, wenn die Druckstufe hoch wird und härtere Folgen nötig sind)."]},
 {a:"Glühwürmchen sind angehalten, alle diese Optionen zu verschiedenen Zeiten zu nutzen, je nachdem, was die Erzählung verlangt. Steigt die Druckstufe, während die Crew auf Reise an Bord ihres Schiffs ist, liefert das Würfeln auf den Zufallstabellen rechts wahrscheinlich etwas Verwertbares. Befindet sich die Crew an einem bestimmten Ort, vielleicht mitten in einer Szene, wenn die Druckstufe steigt, wird ein maßgeschneiderter oder an ihre Situation geknüpfter erzählerischer Ansatz wahrscheinlich besser funktionieren. Und wenn die Spieler bereits mit einer Druckfolge zu tun haben, vermittelt es ein Gefühl logischen Fortschreitens, von immer größerer Anspannung, wenn man sie steigert und wirkungsvoller macht."},
 {h:"Zufällige Druckfolgen"},
 {a:"Für eine zufällige Druckfolge würfle 2W6. Das Ergebnis des ersten W6 bestimmt die Kategorie, die die Folge abdeckt, das zweite beschreibt die erzählerischen oder mechanischen Auswirkungen, mit denen die Crew sich herumschlagen muss, bis sie ihre Druckstufe senkt. Wenn die Crew ihre Druckstufe senkt, während sie unter mehreren Druckfolgen leidet, liegt es beim Glühwürmchen und im Gespräch, zu bestimmen, welche Folge entfällt."},
 {h:"Einzigartige Druckfolgen"},
 {a:"Das Glühwürmchen kann auch einzigartige Druckfolgen aus dem Stegreif erfinden, um sie entweder genauer an die jeweilige Situation oder Umgebung anzupassen, durch die die Crew fährt, oder um ein laufendes Element der Erzählung hervorzuheben oder voranzutreiben. Hier ein Beispiel, wie das aussehen kann, sowohl wenn die Folge zuerst auftritt als auch wenn sie sich bei steigendem Druck entwickelt.\nEine Crew von Dredgern hat es geschafft, einen uralten Sarkophag unbekannter Bauart aus einer astgetragenen Ruine in der Tiefe zu bergen. Sie fahren zurück in die Senke zu einem Tiefhafen, dessen ungefähre Lage sie kennen, doch der Aufstieg ist schwer. Als ihre Druck-Leiste markiert wird, werden mehrere Mitglieder der Unterbesatzung nervös wegen des Funds und weigern sich, den Frachtraum zu betreten, selbst für notwendige Pflichten. Als die Druckstufe steigt, ist von unten ein Poltern zu hören, dann noch eines. Bei der Untersuchung finden sie den Sarkophag offen auf dem Frachtraumboden liegen, das Innere leer. War er vorher leer? Niemand weiß es, doch von diesem Zeitpunkt an wird es für das Schiff immer schwerer aufzusteigen – die Steuerung klemmt und die Motoren stottern, und die Luftwäscher, auf die das Schiff für saubere Luft angewiesen ist, sind mit Honig und Innereien verstopft. Als der Druck erneut steigt, findet ein Schwarm krabbelnder Bienen das Schiff, bedeckt Fenster und macht Navigation fast unmöglich. Mehr Bienen finden ihren Weg durch die zerbrochenen Luftwäscher-Schlote herein, fressen die Leuchtkäfer aus ihren Laternen und stürzen das Schiffsinnere in Dunkelheit. Und im Frachtraum entsteht etwas, ein rasch zusammengesetztes Gebilde aus Waben und Wachs mit dem Sarkophag in der Mitte, mehr Schrein als Bienenstock. Alle Nahrung an Bord beginnt widerlich süß zu schmecken, und die Crew kann nicht einmal ruhen wegen des Summens von Bienen in den Kabinenwänden."},
 {h:"1 – Strukturprobleme"},
 {tab:{k:["W6","Druckfolge","Beschreibung"],z:[
  ["1","Ein Rasseln im Motor","Etwas steckt dort fest oder hat sich losgerüttelt. Es ist nicht unaufhörlich, aber das macht es irgendwie schlimmer."],
  ["2","Gesprungene Bullaugen","Das Bernsteinglas des Schiffs ist unter dem Druck gesprungen. Die Dunkelheit draußen scheint jetzt ein bisschen näher."],
  ["3","Knarren und Splittern","Das Schiff beschwert sich bis in die Knochen. Es kann nicht viel mehr hiervon ertragen, bevor es bricht."],
  ["4","Tiefere Mitternacht","Was auch immer ihr zur Beleuchtung des Schiffsinneren nutzt, flackert schwach oder erlischt ganz."],
  ["5","Luftwäscher-Ausfall","Saubere Luft wird zur fernen Erinnerung, da der Luftwäscher des Schiffs versagt und sich weigert, wieder anzuspringen."],
  ["6","Hüllen-Fehlfunktion","Die Mechanismen, die die Druckhülle über das Deck hebeln, sind verklebt oder funktionieren nicht richtig. Ob die Hülle noch funktioniert, ist fraglich."]]}},
 {h:"2 – Die wilde Tiefe"},
 {tab:{k:["W6","Druckfolge","Beschreibung"],z:[
  ["1","Eisen und Holz","Die Äste um euch sind härter als gewöhnlich und weigern sich, ohne erheblichen Aufwand nachzugeben oder zu brechen."],
  ["2","Etwas in der Luft","… das eure Lunge die Oberfläche vermissen lässt, das eure Haut kribbeln lässt, das euch würgen und prusten lässt."],
  ["3","Zu viel Wuchs","Sporen, Blätter, Blüten – etwas hier weigert sich, aufzuhören zu wachsen, virulent und von impulsiver Gestalt."],
  ["4","Leviathan-Hinterlassenschaften","Vielleicht eine riesige Höhle, ein verlassener Bau oder eine halb aufgefressene Mahlzeit – hier war vor Kurzem etwas."],
  ["5","Brüchig und gebrochen","Jeder Ast, über den das Schiff fährt, droht zu brechen, was das Vorankommen zu einem Albtraum aus Stopp und Start macht."],
  ["6","Fäulnis setzt ein","Die Wellen draußen sind bleich und kränklich, die Rinde löst sich ab und offenbart Schimmel und Insektenbefall in den Ästen. Hoffentlich betrifft diese Seuche nicht das Schiff …"]]}}
]});
L.push({id:"sr-druckfolgen-tabellen", k:K, t:"Zufallstabellen", p:61, q:"sr", b:[
 {h:"3 – Leben in Dunkelheit"},
 {tab:{k:["W6","Druckfolge","Beschreibung"],z:[
  ["1","Schwarmwanderung","Vielleicht eine Masse hungriger Insekten oder eine gefräßige Horde winziger Wesen. Klein, aber in solchen Mengen …"],
  ["2","Neue Bestien, neue Beute","Ein Geschöpf der Tiefe hat eure Witterung und verfolgt euch, um mehr zu erfahren, bevor es zuschlägt."],
  ["3","Plünderer!","Ihr seid nicht die Einzigen mit einem eigenen Tauchboot – eine Plündergruppe hat euch erspäht oder anderweitig eure Spur gefunden und giert nach Beute."],
  ["4","Zweite Runde","Eine Gefahr, die ihr zuvor beseitigt habt, hat überlebt oder wurde durch Crezzer-Verunreinigung oder geistige Besessenheit in neuer Gestalt zurückgebracht. Wie auch immer die Wiederbelebung geschah, sie erinnert sich ganz sicher an euch."],
  ["5","Aus dem Augenwinkel","Etwas Unaussprechliches hat sich in euer Schiff gewunden, in der Hoffnung auf eine Gratisfahrt an einen Ort mit Wärme und Licht und Nahrung."],
  ["6","Behemoth-Signal","Ein Leviathan, leibhaftig, ganz in der Nähe."]]}},
 {h:"4 – Formen unter Druck"},
 {tab:{k:["W6","Druckfolge","Beschreibung"],z:[
  ["1","Fehlfunktion","Ein bewährtes Stück Ausrüstung versagt katastrophal."],
  ["2","Crezzerausbruch","Eine radikale biologische Veränderung durch langsam einsickernde Crezzer-Verderbnis. Wahrscheinlich vorübergehend, aber beunruhigend."],
  ["3","Gewaltsame Auflösung","Flüstern knicken und zerbrechen in deinem Geist, entkommen ungebeten oder zerreißen sich selbst."],
  ["4","Die Hand, die füttert","Ein Gefährte wird von der Tiefe wild gemacht und muss neu abgerichtet oder zurück in die Gruppe gelockt werden."],
  ["5","Unnötige Anpassung","Ein Element deiner Biologie versucht, sich an die erdrückende, lichtlose, astverstopfte Tiefe anzupassen."],
  ["6","Wenn die Erinnerung nicht trügt","Was waren deine Antriebe? Was hat dich dort oben am Laufen gehalten? Was auch immer es war, jetzt hat es sich verändert."]]}},
 {h:"5 – Schwer auf dem Gemüt"},
 {tab:{k:["W6","Druckfolge","Beschreibung"],z:[
  ["1","Die Dunkelheit kriecht herein","Mit jedem Flackern der Schiffslichter wird dein Selbstvertrauen langsam zersetzt. Mit jedem Blick auf ein Bullauge, das in die endlose Nacht draußen führt, fragst du dich, ob du je die Oberfläche wiedersehen wirst."],
  ["2","Seltsame Bettgenossen","Wie viel weißt du wirklich über deine Gefährten? Welche bessere Zeit, in ihre persönlichen Angelegenheiten einzutauchen, als hier unter den Wellen, wo man diesen peinlichen Gesprächen nicht entkommen kann."],
  ["3","Ungebetene Gedanken","Warum hast du diese Entscheidung getroffen? Wer wärst du gewesen, oder mit wem wärst du zusammen gewesen, wenn nicht? Vergangene Entscheidungen sind eine Zeit lang unmöglich hinter sich zu lassen."],
  ["4","Alles gleich","Sicher seid ihr schon einmal an diesem Ort vorbeigekommen – ist das Unterblätterdach nichts als ein Irrgarten, ein lichtloses Labyrinth, das ihr nie hättet zu durchqueren versuchen sollen?"],
  ["5","Etwas fehl am Platz","Eine Entdeckung, die mehr Fragen als Antworten aufwirft, etwas von der weit entfernten Oberfläche hier unten in der Tiefe. Wer hat es gebracht, und warum, und solltet ihr es zu ihnen zurückbringen oder als Denkmal ihrer Mühe stehen lassen?"],
  ["6","Wir waren nicht die Ersten","Ein Zeichen, dass andere Wildsegler an diesen Ort kamen. Diese Wegbereiter sind längst fort. Du weißt wahrscheinlich, wo sie gelandet sind."]]}},
 {h:"6 – … Und dann war keiner mehr da"},
 {tab:{k:["W6","Druckfolge","Beschreibung"],z:[
  ["1","Neues Gesicht in der Menge","Eine Kopfzählung ergibt ein Mitglied der Unterbesatzung mehr, als da sein sollten, doch alle erinnern sich aneinander … Ist die Zählung falsch, oder die Welt?"],
  ["2","Schlampig","Der Druck wird einem der Unterbesatzung zu viel, und er macht an seinem Posten einen kritischen Fehler."],
  ["3","Verstummt","Stille sucht die Decks heim wie ein unwillkommener Gast, die Unterbesatzung zögert zu reden, selbst miteinander."],
  ["4","Verwildert","Unterbesatzungs-Rudel werden wild, schnappen nach ihren Gefährten und verlassen ihre Posten."],
  ["5","Einfach … fort","Ein Mitglied einer Bande der Unterbesatzung ist verschwunden, alle seine Kollegen schwören, sie hätten ihn noch einen Moment zuvor gesehen."],
  ["6","Über jeder Schulter","Ein Mitglied der Unterbesatzung schwört, es habe draußen etwas gesehen, etwas, das es beobachtet, es verfolgt."]]}}
]});
L.push({id:"sr-druck-optionen", k:K, t:"Mechanische Druckoptionen", p:62, q:"sr", b:[
 {a:"Während die erzählerischen Folgen von Druck jede Gruppe selbst ausarbeiten muss, hast du hier einige feste Optionen, wenn der wachsende Druck auf Schiff und Crew eine mechanische Darstellung braucht."},
 {c:"Schaden zufügen", x:"Ein einfach zu nutzender Effekt: Wähle eine Schadensart und -menge, die zur Erzählung der Druckfolge passt. Dornenranken, die durch ein Bullauge platzen, könnten zum Beispiel 3 Markierungen Stichschaden verursachen."},
 {c:"Einen Effekt oder Morast zufügen", x:"Eine Komplikation, die die Erzählung für ein oder mehrere Crewmitglieder beeinflusst, möglicherweise auch Morast verursacht. Dieselben Dornenranken könnten sich stattdessen um zwei Crewmitglieder wickeln und sie zwingen, sich zu befreien, bevor sie sich wieder bewegen können."},
 {c:"Verbrennung zufügen", x:"Wenn die Druckstufe steigt, kann Verbrennung ernstere Verletzungen oder bleibende Probleme bewirken. Eine Säureflut, die über die Druckhülle des Schiffs schwappt, könnte ein oder zwei Kästchen auf der Dichtungs- oder Panzerungs-Leiste verbrennen, unmöglich zu reparieren ohne umfangreichen Umbau und die richtigen Materialien."},
 {c:"Eine Ressource oder Fracht verbrauchen/verschlechtern", x:"Oder einen ganzen Ressourcentyp, wenn die Druckstufe hoch wird. Dieselbe Säureflut könnte stattdessen allen metallbasierten Ressourcen jeder davon erfassten Crew die Markierung „korrodiert“ hinzufügen oder ein paar ihrer Ressourcen oder Frachtstücke ganz auflösen."},
 {c:"Zugang zu einer Fertigkeit / Sprache / Stärke verlieren", x:"Besonders nützlich bei eher psychologischen Druckereignissen: Ein Crewmitglied könnte den Zugang zu einer seiner Fertigkeiten oder Stärken verlieren, bis der Druck ein wenig nachlässt. Ablenkende Ausbrüche hypnotischer Photophoren von außerhalb des Schiffs könnten ein Crewmitglied ablenken, sodass es die Schleier- oder Gezeiten-Stärke nicht nutzen kann, bis das Schiff weitergezogen ist, oder es daran hindern, seine Fertigkeiten Spüren oder Studieren zur Unterstützung von Aktionswürfen zu nutzen."},
 {c:"Zusätzlicher Abzug / Verringerte Wucht", x:"Im Moment besonders hart treffend. Dieselben photophorischen Blitze könnten stattdessen allen Würfen Abzug hinzufügen, die zum Konzentrieren oder entschlossenen Handeln gemacht werden, oder sogar die Wucht aller geistesbasierten Aktionen verringern, um die ständige Ablenkung darzustellen."},
 {h:"Druck auf Druck auf Druck …"},
 {a:"Eine Crew, die beim tieferen Abtauchen durch sehr unterschiedliche Bereiche fährt, gerät wahrscheinlich unter den Einfluss mehrerer verschiedener Druckfolgen, von denen manche sich im Verlauf der Reise abschwächen oder verschlimmern. Wenn die Druckstufe steigt und eine neue Folge hinzukommt, überlege, ob sie:"},
 {l:["das Schiff, die Umgebung, die ganze Crew oder ein einzelnes Crewmitglied betrifft","ein völlig neuer Effekt oder eine Verstärkung/Verschlimmerung eines früheren Effekts ist","etwas ist, das die Crew sofort bemerkt, oder etwas, das ihr nur langsam bewusst wird (oder das sie erst im schlimmstmöglichen Moment bemerkt oder erkennt)"]},
 {a:"Je höher die Druckanzeige, desto härter sollten die Druckfolgen sein – je nach Erzählung kann es beim Erreichen einer neuen Druckstufe mehrere verschiedene mechanische Effekte geben. Hier ein Beispiel:\nDie Crew der Kalen’s Falcon taucht tiefer als das Gestrüpp ab. Als ihre Druckanzeige eins erreicht, wird die Luft um das Schiff feindselig, säurehaltig – alle Crewmitglieder erleiden mittleren Säureschaden, wenn sie die Sicherheit des Schiffsinneren oder der Druckhülle über dem Deck verlassen. Sie schaffen es, die Druckanzeige erneut auszureizen, bevor sie die Senke erreichen, und das kostet sie ein Mitglied der Unterbesatzung an groteske Pilzranken, die durch Spalten im Schiff gleiten.\nDieselben Ranken stehlen auch ein wertvolles Frachtstück – es ist nicht zerstört, aber die Crew muss das Schiff verlassen, um es zurückzuholen. Sie verfolgen diese Fracht nach unten und dringen in die Senke ein – nicht nur stehen sie dem pseudopodialen myconischen Schrecken gegenüber, der ihr Schiff verwüstet, der Anstieg der Druckstufe bringt auch ein Wiederaufflammen der säurehaltigen Luft mit sich. Der Säureschaden, den sie für das Verlassen des Schiffs erleiden, wird zu Verbrennung, und ihre Gefährten weigern sich, sie dort hinaus in die Dunkelheit zu begleiten, wodurch sie den Zugang zu allen Gefährten-Aspekten verlieren, bis die Druckstufe sinkt.\nUnwillig, sich in diesem Maß zu riskieren, fliehen sie, lassen ihre Fracht zurück und finden ihren Weg zum nächsten Tiefhafen, einer bernsteinbekuppelten Umgebung, die den säurehaltigen Lüften der Gegend widersteht. Das Anlegen dort senkt ihre Druckstufe auf zwei, und die Säure lässt nach. Zudem decken sie sich mit örtlicher Schutzausrüstung ein, was die Wirkung der säurehaltigen Luft im Wesentlichen auf null senkt, bis sie bereit sind, erneut jenes tentakelbewehrte Ungeheuer zu jagen."},
 {h:"Wenn die Anzeige drei erreicht"},
 {a:"Die Druckanzeige erreicht ihr Maximum bei Tiefenstufe drei, aber das heißt nicht, dass es nicht noch schlimmer kommen kann. Markiere die Leiste weiter – statt zu steigen, wenn das letzte Kästchen markiert wird, verschlimmert sich jede bestehende Druckfolge, unter der die Crew leidet. Der Verlust eines einzelnen Unterbesatzungs-Mitglieds könnte stattdessen der Verlust einer ganzen Bande werden, leichter oder mittlerer Schaden durch einen andauernden Umgebungseffekt kann auf schweren Schaden oder gar Verbrennung steigen, und zwingender Abzug, der eine einzelne Art von Aktion betrifft, kann sich auf verwandte Tätigkeiten ausbreiten oder weit schwerer werden."}
]});
L.push({id:"sr-druck-mildern", k:K, t:"Abmildern oder fliehen?", p:63, q:"sr", b:[
 {a:"Die Tiefen der Wildsee sind feindselig, gelegentlich überwältigend, aber nicht unbezwingbar (zumindest vorübergehend). Statt den durch das tiefere Abtauchen verursachten Druckfolgen zu entkommen, sollten Crews versuchen, kluge Wege zu finden, sie abzumildern oder mit ihnen zu arbeiten, indem sie sich selbst und ihre Schiffe an die Gefahren anpassen, denen sie begegnen. Hier ein Beispiel, das an die vorherige verhängnisvolle Situation anschließt, als hätte die Crew der Kalen’s Falcon keinen nahen Tiefhafen, den sie ansteuern könnte."},
 {a:"Es gibt viele Wege, mit Druckfolgen umzugehen, und selbst wenn du den Druck, unter dem du stehst, nicht immer verringern kannst, kannst du meist zumindest etwas tun, um ihn ein wenig weniger bedrückend zu machen. Eine kluge Crew könnte:"},
 {l:["sich so gut wie möglich auf ein Abtauchen vorbereiten und Ressourcen und Frachtstücke mitnehmen, von denen sie aufgrund früherer Erkundungen wissen, dass sie im Notfall nützlich sind","Tiefhäfen aufsuchen und ihre Dienste und ihr Wissen über die Tiefe nutzen, um sich das Leben leichter zu machen, das Schiff mit neuen Aufrüstungen auszustatten oder der Crew vorübergehende Vorteile zu verschaffen","der Wildnis den Kampf ansagen – statt sich im Schiff zu ducken, um einem jagenden Geschöpf oder einem Umgebungseffekt zu entkommen, kann eine Crew sich ihm direkt stellen und kurzfristigen Schmerz gegen längerfristige Sicherheit tauschen"]},
 {bsp:"Druckfolgen im Spiel", z:[
  ["Kyllian","Wir gehen tiefer. Und ja, wir wissen, dass das eine schreckliche Idee ist."],
  ["Todd","Fairerweise ist das die Hälfte des Grundes, warum wir es tun."],
  ["Glühwürmchen","Okay, das Arbo-Tiefenmessgerät eures Schiffs klirrt und protestiert, als ihr euch von der Senke hinunter in die dünnere, lichtlose Welt der Tiefe schneidet. Die Motten, die das Schiff die letzten Szenen über bedrängt haben, geben endlich auf, geschlagen von den neuen Tiefen, die ihr erreicht habt. Aber …"],
  ["Kyllian","Ich sehe, dass du da Würfel rollst …"],
  ["Glühwürmchen","Richtig, es können nicht nur gute Nachrichten sein. Ich erhöhe die Druckstufe – ihr seid jetzt bei zwei, also wird es brenzlig. Zuerst einmal: Diese Motten sind aus gutem Grund gegangen – einer eurer Unterbesatzungs-Offiziere taumelt nach den ersten paar Minuten in den Raum und schwadroniert über etwas, das er draußen an Deck unter der Hülle gesehen hat. Ich markiere diesen Offizier."],
  ["Kyllian","Wir sind also nicht allein hier unten."],
  ["Glühwürmchen","Niemals. Aber das ist nicht euer einziges Problem. Kyllian, sein Gerede erinnert dich an etwas, etwas aus deiner Vergangenheit – etwas, das du gesehen hast, als du tiefer warst, als du solltest, und weit schlechter vorbereitet. Du warst ohnehin beklommen, hier unten zu sein … War dieser alte Geist von einem Gedanken der Grund?"],
  ["Kyllian","Höchstwahrscheinlich ja. Ich erzähle hier gern eine Geschichte – wird es irgendeine Art Nachwirkung geben?"],
  ["Glühwürmchen","Allerdings – während dein Geist von diesem alten Schrecken beschäftigt ist, erleidest du Abzug auf alle Aktionen, die Konzentration erfordern …"]]},
 {a:"Die Lage sieht schlecht aus – die Crew hat ihre Gefährten-Aspekte nicht zur Verfügung, und jede Unternehmung außerhalb des Schiffs wird ernste Mengen Säureschaden verursachen (als Verbrennung statt als Markierungen, was die Lage noch verschlimmert). Außerdem verfolgt sie ein Pilzschrecken, der bereits ein Mitglied ihrer Unterbesatzung und ein Frachtstück gefordert hat.\nAber wenn die Crew der Falcon vernünftige Leute wäre, wäre sie gar nicht erst in der Tiefe. Ihr Alchemist beginnt an einer Gegenchemikalie zu arbeiten, etwas, das die Säure lange genug neutralisieren könnte, damit ihr Corsair hinausgehen und die Deckwaffen des Schiffs neu ausrichten kann. Sie können ihren myconischen Feind vielleicht nicht besiegen, aber wenn sie ein paar solide Treffer landen, zieht sich das Ding vielleicht zurück und verschafft ihnen eine Atempause, und sei es nur ein Moment, um den nächsten verzweifelten Schritt zu planen."}
]});
L.push({id:"sr-risse", k:K, t:"Risse", p:64, q:"sr", b:[
 {erz:"Leth hatte sich immer gesagt, dass es so etwas wie Glück nicht gebe, dass selbst jene, die schworen, ihr Schicksal werde von etwas Unerkennbarem begünstigt (oder verflucht), sich in Wahrheit nur selbst etwas vormachten.\nDie Ereignisse der vergangenen Woche hatten diese Ansicht nicht erschüttert, aber sie hatten durchaus einige andere Gewissheiten losgerüttelt. Der Motor, der nicht einmal, sondern dreimal ausfiel, die Stelle, die sie zum Ankern in der Tiefe gewählt hatten, überrannt von massiven wandernden Spinnentieren, selbst die Fracht, die sie aus dem einzigen Wrack geborgen hatten, auf das sie gestoßen waren, und die sich als nichts als zwanzig Kisten längst verdorbener Wurmäpfel herausstellte.\nEs war kaum die erfolgreichste Expedition gewesen, und soweit es Leth betraf, hatten sie eine Rückkehr an einen sicher nautilisierten Ort und ein Bad in einer Schattenquelle verdient.\nIm Positiven: Schlimmer konnte es kaum werden."},
 {a:"Ein verlässlicher Weg, die Zahl der Markierungen auf deiner Druckanzeige zu senken: Ein Riss ist eine verwilderte Wendung."},
 {h:"Riss-Mechanik"},
 {a:"Einmal pro Szene kannst du, wenn du eine Wendung würfelst, beschließen, sie stattdessen als Riss zu behandeln. Wenn du das tust, leere sofort eine Markierung auf der Druck-Leiste.\nNur ein Spieler kann pro Szene einen Riss nutzen, und er muss erklärt werden, bevor die Wendung, die er ersetzt, besprochen wird (das heißt, du kannst nicht im Gespräch herausfinden, was die Wendung sein könnte, und dich dann für einen Riss entscheiden)."},
 {h:"Risse in der Erzählung"},
 {a:"Ein Riss funktioniert in den meisten Punkten wie eine Wendung – er wird dem Rest des Tisches zur Besprechung geöffnet, um etwas Unerwartetes zu finden, das sich infolge deiner Handlungen ereignet.\nAnders als eine Wendung ist ein Riss immer etwas Negatives – vielleicht sogar für alle Beteiligten, aber immer zumindest für den, der ihn gewürfelt hat, sein Schiff oder seine Crewkameraden. Außerdem sollte dieser Riss die Form eines tiefenbezogenen Ereignisses haben, etwas, das dadurch verursacht wird, dass Schiff und Crew unter Druck stehen.\nRisse müssen kein mechanisches Element haben (können es aber durchaus), doch sie sollten ganz entschieden den Fluss der Erzählung verändern und sowohl dem Glühwürmchen als auch der Crew eine neue Herausforderung geben oder eine Dimension der Geschichte hinzufügen, mit der man arbeiten oder auf die man reagieren kann."},
 {h:"Beispiel-Risse"},
 {a:"Die Freiheit, die Wendungen bieten, kann für manche Spieler schwer zu verinnerlichen sein, und bei Rissen ist es nicht anders. Um die mögliche kreative Last hoffentlich zu verringern, haben wir unten einige Beispiele ergänzt, wie sich Risse unten zeigen könnten.\nEin Riss könnte die Form haben von:"},
 {l:["Einer plötzlichen Veränderung der Umgebung durch die unbekannten Gefahren der Tiefe (etwa ein Ausbruch von Sporen oder das Splittern von Deckholz).","Einer Veränderung der Wahrnehmung oder Perspektive oder einem aufdringlichen Gedanken, den du nicht anders kannst, als ihn dich beeinflussen zu lassen.","Einer plötzlichen Mutation oder der Enthüllung eines unerwarteten Crezzerin-basierten Effekts bei einer Gefahr, der du gegenüberstehst."]},
 {a:"Als zusätzliche Anleitung nehmen wir eine für Erkunder der Tiefe häufige Situation – den Anblick einer schrecklichen Kreatur, möglicherweise eines Leviathans, der der Druck-Leiste eine Markierung hinzufügt, obwohl sie die Charaktere noch gar nicht bemerkt hat. Eine Crew, die in einer solchen Situation einen Riss festlegt, könnte beschließen:"},
 {l:["Die Kreatur bemerkt einfach das Schiff und rückt näher, um es zu untersuchen.","Ein neues Merkmal oder Element der Kreatur beschreiben, das bei einer Veränderung der Lage offensichtlich wird, etwa eine Schar kleinerer Begleiter oder Junge, die an der Unterseite des Wesens hängen.","Etwas mit dem Schiff geschehen lassen, wie das Platzen eines Druckventils oder ein unerwartetes Brüllen eines instabilen Motors, das die Kreatur aufweckt und sie dazu bringt, die Gegend zu untersuchen.","Einen Begleiter oder Rivalen des Ungeheuers einführen, der sein Verhalten von passiv zu aktiv ändert; selbst wenn das keine unmittelbare Bedrohung darstellt, erschwert es die Lage und erhöht die künftige Gefahr.","Ein Mitglied der Unterbesatzung in die Kajüte taumeln lassen – das ist die Kreatur, stammelt es, die seinen Freund (oder seine Familie oder gar seinen ganzen Spit) gefressen hat. Es wird verständlicherweise aufgewühlt und für den Rest der Szene und vielleicht darüber hinaus unzuverlässig sein."]}
]});
L.push({id:"sr-risse-spiel", k:K, t:"Risse im Spiel", p:65, q:"sr", b:[
 {bsp:"Risse im Spiel", z:[
  ["Glühwürmchen","Ihr hört, wie die Struktur des Schiffs um euch knarrt und sich verschiebt, die Dornenranken drücken so dicht gegen das Bernsteinglas, dass ihr kaum etwas anderes dort draußen sehen könnt."],
  ["Laura","Okay … Aber wir wissen, dass wir nicht allein sind, oder?"],
  ["Glühwürmchen","Oh ja. Ihr wisst. Ich markiere die Druckanzeige, nicht nur wegen der Dornenranken, sondern wegen des Wissens, dass sich etwas Leviathan-Großes in der Nähe durch sie bewegt."],
  ["Kyllian","Ich denke, wir könnten einen Blick darauf werfen – nicht dass ich das besonders will, nur dass es vernünftig wäre. Ich habe dieses Schwarmsicht-Gebräu, das ich vorhin gemacht habe – kann ich einen Schluck nehmen und einen Blick darauf erhaschen, was da draußen ist?"],
  ["Glühwürmchen","Natürlich, nur zu. Du musst allerdings würfeln, um einen guten Blick zu bekommen."],
  ["Kyllian","Okay, ich markiere diese temporäre Leiste, um etwas von dem Gebräu zu trinken und meine Sicht durch alle Insekten dort draußen zu lenken, und ich würfle Studieren, um Informationen über das Ding zu bekommen. Das sind 2W6 für Studieren, 1W6 für Schleier und … Zählt das Gebräu als Vorteil?"],
  ["Glühwürmchen","Oh, definitiv."],
  ["Kyllian","Dann 4W6 … Eine 5, eine 4 und zwei 1en. Das ist eine Wendung, aber … Angesichts dieser Druck-Markierung nehme ich sie, glaube ich, als Riss."],
  ["Glühwürmchen","Dann leere ich diese Markierung. Machen wir den Riss vor dem Konflikt – irgendjemand, irgendwelche Ideen?"],
  ["Todd","Ooh, wie wäre es, wenn Kyllian das Ding sieht, das da draußen war, aber es ist genauso gefangen wie wir in diesen Dornenranken, und das zieht mehr Aufmerksamkeit von örtlichen Raubtieren an?"],
  ["Glühwürmchen","Also ist ein Schwarm unterwegs? Mir gefällt das, wenn es dir passt, Kyllian. Nun, mit dem Konflikt-Ergebnis siehst du …"]]}
]});
})(WS_NACH.regeln);
